<script setup>
import { ref } from "vue";
import { ArrowUpRight, FileText, FolderOpen, LoaderCircle, RefreshCw } from "@lucide/vue";
import { appInfo, displayVersion } from "../lib/app-info";
const props=defineProps({update:{type:Object,required:true},autoCheck:Boolean,checkUpdates:{type:Function,required:true},setAutoCheck:{type:Function,required:true},openExternal:{type:Function,required:true},openLogs:{type:Function,required:true}});
const error=ref("");
const emit=defineEmits(["setup"]);
async function toggleAuto(event){error.value="";try{await props.setAutoCheck(event.target.checked);}catch(failure){error.value=failure.message;event.target.checked=props.autoCheck;}}
async function openLink(url){error.value="";try{await props.openExternal(url);}catch(failure){error.value=failure.message;}}
</script>
<template><div class="about-settings"><div class="about-identity"><span class="about-mark"><img src="/brand/mumu.png" width="80" height="80" alt="沐沐" /></span><h3>{{appInfo.name}}</h3><span class="about-version">版本 {{displayVersion}}</span><button class="text-button" type="button" @click="openLink(appInfo.repository)">项目主页<ArrowUpRight :size="14" /></button></div><section class="about-updates"><label class="preference-row"><span><strong>自动检查更新</strong><small>启动时检查已发布版本</small></span><input class="switch-input" type="checkbox" role="switch" aria-label="自动检查更新" :checked="autoCheck" @change="toggleAuto"></label><button class="button dark about-check-button" type="button" :disabled="update.status==='checking'" @click="checkUpdates"><LoaderCircle v-if="update.status==='checking'" class="spinning" :size="15" /><RefreshCw v-else :size="15" />{{update.status==='checking'?'正在检查':'检查更新'}}</button><div class="about-update-status" :class="{error:update.status==='error'}" role="status"><span>{{update.message}}</span><button v-if="update.status==='available'" class="text-button" type="button" @click="openLink(update.url)">查看新版本<ArrowUpRight :size="13" /></button></div><time v-if="update.checkedAt">上次检查 {{new Date(update.checkedAt).toLocaleString('zh-CN',{hour12:false})}}</time></section><div class="about-links"><button class="text-button" type="button" @click="emit('setup')"><RefreshCw :size="15" />重新初始化</button><button class="text-button" type="button" @click="openLink(appInfo.repository+'/releases')"><FileText :size="15" />查看更新记录</button><button class="text-button" type="button" @click="openLogs"><FolderOpen :size="15" />打开日志目录</button></div><p v-if="error" class="validation-error" role="alert">{{error}}</p></div></template>
<style scoped>
.about-settings{max-width:720px;padding:12px 0 24px;}.about-identity{display:flex;flex-direction:column;align-items:center;gap:13px;padding:20px 0 34px;}.about-mark{display:grid;place-items:center;width:64px;height:64px;color:var(--accent);}.about-identity h3{font-size:24px;font-weight:600;line-height:1.4;text-align:center;}.about-version{font-size:12px;color:var(--muted);}.about-identity .text-button,.about-links .text-button{display:flex;align-items:center;gap:7px;}.about-updates{padding:10px 0 22px;border-block:1px solid var(--line);}.about-check-button{width:100%;margin-top:15px;min-height:38px;}.about-update-status{display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:8px;min-height:36px;margin-top:10px;color:var(--green);font-size:12px;text-align:center;}.about-update-status.error{color:var(--red);}.about-updates>time{display:block;text-align:center;color:var(--muted);font-size:10px;margin-top:5px;}.about-links{display:flex;justify-content:center;flex-wrap:wrap;gap:20px;margin-top:28px;}.about-settings>.validation-error{font-size:12px;margin-top:18px;text-align:center;}
</style>
